B.a3o=new A.ad(983471,"MaterialIcons",null,!1)
B.Nv=new A.eM(B.a3o,"Reworked app shell","A clearer overview and section layout make core workflows easier to discover.")
B.a32=new A.ad(63216,"MaterialIcons",null,!1)
B.NE=new A.eM(B.a32,"Stereo devices","Device pairs like earables can now be displayed as a stereo pair, making it easier to manage and interact with them.")
B.a30=new A.ad(63144,"MaterialIcons",null,!1)
B.NG=new A.eM(B.a30,"Better device journeys","Connection, inspection, and update-related actions are easier to reach and expand over time.")
B.a3z=new A.ad(983942,"MaterialIcons",null,!1)
B.NK=new A.eM(B.a3z,"Improved sensor workflows","Configuration, live data, and recording fit into a more coherent structure.\nSave custom sensor profiles and apply them to your devices to quickly switch between different sensor configurations.")
B.a3k=new A.ad(983396,"MaterialIcons",null,!1)
